/** Translate a SANY catalog name (category, subcategory, or spec group) to the given language. */
export function translateSanyName(
  name: string,
  language: string,
  map: LangMap,
): string {
  const entry = map[name];
  if (!entry) return name;
  if (language === "en") return entry.en ?? name;
  return entry[language as "fr" | "es"] ?? name;
}

