/** Translate a SANY feature title and its description. Falls back to source. */
export function translateSanyFeature(
  title: string,
  description: string,
  language: string,
): { title: string; description: string } {
  const feat = SANY_FEATURES[title];
  if (!feat) return { title, description };
  if (language === "en") {
    return {
      title: feat.title.en ?? title,
      description: feat.description?.en ?? description,
    };
  }
  return {
    title: feat.title[language as "fr" | "es"] ?? title,
    description: feat.description?.[language as "fr" | "es"] ?? description,
  };
}

/**
 * Translate a SANY spec value or `valueWithUnit`. Numeric/unit-only values are
 * returned unchanged; only descriptive values present in `SANY_SPEC_VALUES`
 * are translated.
 */
export function translateSanySpecValue(
  value: string,
  language: string,
): string {
  return translateSanyName(value, language, SANY_SPEC_VALUES);
}
